attributes.cssVariables:
:root {
  --font-sans: 'IBM Plex Sans', ui-sans-serif, system-ui, sans-serif;
  --font-serif: 'IBM Plex Serif', ui-serif, Georgia, serif;
  --font-mono: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  --background: #f7f8fa;
  --card: #ffffff;
  --foreground: #16161a;
  --card-foreground: #16161a;
  --muted: #eef0f3;
  --muted-foreground: #656a73;
  --border: #dfe2e7;
  --input: #dfe2e7;
  --primary: #00a884;
  --primary-foreground: #071b17;
  --accent: #00a884;
  --accent-foreground: #071b17;
  --ring: #00a884;
  --radius: 0.625rem;
  --family-objects: #2f80ed;
  --family-objects-soft: #eaf3ff;
  --family-properties: #6aa84f;
  --family-properties-soft: #eff8e9;
  --family-actions: #7657e8;
  --family-actions-soft: #f0edff;
  --family-interfaces: #e49332;
  --family-interfaces-soft: #fff4e5;
  --family-intelligence: #dc526f;
  --family-intelligence-soft: #fff0f4;
  --family-rules: #168c8c;
  --family-rules-soft: #e8f7f7;
  --family-bsl: #353740;
  --family-bsl-soft: #eef0f3;
  --status-proven: #8fca00;
  --status-ready: #00a884;
  --status-planned: #a9adb5;
  --shadow-sm: 0 1px 2px rgba(16, 20, 28, 0.08);
  --shadow-md: 0 12px 34px rgba(16, 20, 28, 0.10);
}
